def extract(tree):
    rows = tree.where(content_desc="sourceLanguagePicker")
    if not rows:
        raise ValueError("Source language picker is absent")
    return "English" in rows[0]["name"]

def extract(tree):
    rows = tree.where(content_desc="targetLanguagePicker")
    if not rows:
        raise ValueError("Destination language picker is absent")
    return "Spanish" in rows[0]["name"]

